export const SCREEN_COUNT = SCREENS.length;
export function screenByHref(href: string) {
  const clean = href.replace(/\/+$/, "") || "/";
  return SCREENS.find((s) => s.href === clean) ?? SCREENS.find((s) => s.route === clean.replace(/^\/staff/, "") || s.href === clean);
}
